import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../../localization/app_strings.dart';
import '../../models/conversation_topic_model.dart';
import '../../services/conversation_topic_service.dart';

class ConversationTopicsScreen extends StatefulWidget { const ConversationTopicsScreen({super.key}); @override State<ConversationTopicsScreen> createState()=>_ConversationTopicsScreenState(); }
class _ConversationTopicsScreenState extends State<ConversationTopicsScreen> {
  late final ConversationTopicService service; late final String userId; String category='conversation';
  final Map<String,TextEditingController> answers={};
  @override void initState(){super.initState(); final c=Supabase.instance.client; service=ConversationTopicService(c); userId=c.auth.currentUser?.id ?? '';}
  @override void dispose(){for(final c in answers.values)c.dispose(); super.dispose();}
  TextEditingController _answer(String id){return answers.putIfAbsent(id,()=>TextEditingController());}
  Future<void> _add() async {final s=AppStrings.of(context); final c=TextEditingController(); final value=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:Text(s.addYourOwnTopic),content:TextField(controller:c,autofocus:true,maxLines:3,decoration:InputDecoration(hintText:s.topicQuestion)),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:Text(s.cancel)),FilledButton(onPressed:()=>Navigator.pop(ctx,c.text),child:Text(s.save))])); if(value==null||value.trim().isEmpty)return; try{await service.addTopic(userId:userId,prompt:value); if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s.topicAdded)));}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s.topicSaveFailed)));}}
  @override Widget build(BuildContext context){final s=AppStrings.of(context); final scheme=Theme.of(context).colorScheme; return Scaffold(appBar:AppBar(title:Text(s.conversationFinder),actions:[IconButton(onPressed:_add,icon:const Icon(Icons.add_rounded))]),body:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(16,12,16,8),child:SegmentedButton<String>(segments:[ButtonSegment(value:'conversation',label:Text(s.conversationTopics),icon:const Icon(Icons.forum_outlined)),ButtonSegment(value:'joke',label:Text(s.jokes),icon:const Icon(Icons.sentiment_very_satisfied_outlined))],selected:{category},onSelectionChanged:(v)=>setState(()=>category=v.first))),Expanded(child:StreamBuilder<List<ConversationTopic>>(stream:service.streamTopics(),builder:(context,snap){if(snap.hasError)return Center(child:Text(s.topicsLoadFailed));final topics=(snap.data??[]).where((t)=>t.category==category).toList(); if(topics.isEmpty)return Center(child:Text(s.noTopics)); return StreamBuilder<List<ConversationTopicProgress>>(stream:service.streamProgress(userId),builder:(context,ps){final progress={for(final p in (ps.data??[]))p.topicId:p}; return ListView.separated(padding:const EdgeInsets.fromLTRB(16,8,16,28),itemCount:topics.length,itemBuilder:(ctx,i){final t=topics[i];final p=progress[t.id];final ac=_answer(t.id);if(p!=null&&ac.text.isEmpty)ac.text=p.answer;final asked=p?.asked??false;return Material(color:scheme.surface,borderRadius:BorderRadius.circular(20),elevation:1,child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:Text(t.prompt(s.code),style:const TextStyle(fontSize:16,fontWeight:FontWeight.w800,height:1.35))),Checkbox(value:asked,onChanged:(v) async{await service.saveProgress(userId:userId,topicId:t.id,asked:v??false,answer:ac.text);})]),const SizedBox(height:8),TextField(controller:ac,minLines:1,maxLines:4,onSubmitted:(_)=>service.saveProgress(userId:userId,topicId:t.id,asked:asked,answer:ac.text),decoration:InputDecoration(labelText:s.answerOptional,prefixIcon:const Icon(Icons.edit_note_rounded),border:OutlineInputBorder(borderRadius:BorderRadius.circular(14))),onChanged:(_){},),Align(alignment:Alignment.centerRight,child:TextButton.icon(onPressed:()=>service.saveProgress(userId:userId,topicId:t.id,asked:asked,answer:ac.text),icon:const Icon(Icons.save_outlined),label:Text(s.save))) ])));},separatorBuilder:(_,__)=>const SizedBox(height:10));});}))]));}
}
